package br.com.election;
import br.com.election.readiness.*;
import br.com.election.aggregate.*;
import br.com.election.poll.*;
import br.com.election.pollster.*;
import br.com.election.tse.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import tools.jackson.databind.json.JsonMapper;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @Import(TestcontainersConfiguration.class)
class ReadinessIntegrationTests {
 @Autowired BatchImportService imports;@Autowired DataQualityService quality;@Autowired FreezeService freezes;
 @Autowired AggregateAuditService audit;@Autowired PollService polls;@Autowired PerformanceCalculationService calculations;
 @Autowired PreElectionComparisonService comparison;@Autowired JdbcTemplate jdbc;@Autowired JsonMapper json;@Autowired MockMvc mvc;
 @BeforeEach void clean(){jdbc.execute("TRUNCATE pre_election_freezes");jdbc.update("DELETE FROM aggregate_snapshots");jdbc.update("DELETE FROM polls");jdbc.update("DELETE FROM pollster_performance");jdbc.update("UPDATE pollsters SET active=true");jdbc.update("UPDATE candidates SET active=true");}
 @AfterEach void cleanup(){jdbc.execute("TRUNCATE pre_election_freezes");jdbc.update("DELETE FROM aggregate_snapshots");jdbc.update("DELETE FROM polls");jdbc.update("DELETE FROM pollster_performance");}
 String row(String registration,int first){return """
 {"pollsterSlug":"datafolha","tseRegistrationNumber":%s,"fieldStart":"2026-10-18","fieldEnd":"2026-10-20","publishedAt":"2026-10-21T12:00:00Z","sampleSize":1500,"marginOfError":2,"methodology":"SYNTHETIC TEST","sourceUrl":"https://example.org/synthetic","voteBasis":"TOTAL","candidateResults":[{"ballotNumber":22,"percentage":%d},{"ballotNumber":13,"percentage":%d}]}
 """.formatted(registration==null?"null":"\""+registration+"\"",first,100-first);}
 String performance(){return """
 {"pollsterSlug":"datafolha","electionKey":"BR-PRESIDENT-2026","round":1,"candidateError":1,"spreadError":3,"sourceUrl":"https://example.org/synthetic-history","sourceDescription":"Synthetic test only","notes":"Not electoral evidence"}
 """;}
 ImportModels.Report run(String rows,boolean dry){return imports.run(json.readTree("["+rows+"]"),dry,false);}
 void seed(){assertThat(run(row("TEST-ONLY",60),false).created()).isEqualTo(1);}
 PreElectionFreeze freeze(){return freezes.create(new FreezeService.Request("Synthetic test",null,"Do not publish"));}
 @Test void validImportUsesIndividualNormalization(){var r=run(row("TEST",45).replace("\"percentage\":55","\"percentage\":35"),false);assertThat(r.created()).isEqualTo(1);assertThat(polls.list().getFirst().results()).extracting(PollResponse.Result::normalizedPercentage).contains(new BigDecimal("56.2500"),new BigDecimal("43.7500"));}
 @Test void dryRunDoesNotPersistAndShowsNormalization(){var r=run(row("TEST",60),true);assertThat(r.created()).isEqualTo(1);assertThat(r.details().getFirst().normalized()).isNotNull();assertThat(polls.list()).isEmpty();}
 @Test void reimportIsIdempotentDespiteDecimalScale(){seed();var r=run(row("TEST-ONLY",60),false);assertThat(r.unchanged()).isEqualTo(1);assertThat(polls.list()).hasSize(1);}
 @Test void updatePreservesPollId(){seed();var id=polls.list().getFirst().id();assertThat(run(row("TEST-ONLY",55),false).updated()).isEqualTo(1);assertThat(polls.list().getFirst().id()).isEqualTo(id);}
 @Test void dryRunUpdateDoesNotMutateExistingPoll(){seed();var before=polls.list();assertThat(run(row("TEST-ONLY",55),true).updated()).isEqualTo(1);assertThat(polls.list()).isEqualTo(before);}
 @Test void failureIsIsolatedAndLaterValidRowsPersist(){var r=run(row("A",60)+","+row("BAD",55).replace("datafolha","unknown")+","+row("B",50),false);assertThat(r.created()).isEqualTo(2);assertThat(r.failed()).isEqualTo(1);assertThat(polls.list()).hasSize(2);}
 @Test void fallbackKeyIsIdempotent(){assertThat(run(row(null,60),false).created()).isEqualTo(1);assertThat(run(row(null,60),false).unchanged()).isEqualTo(1);assertThat(run(row(null,55),false).updated()).isEqualTo(1);}
 @Test void duplicateRowsWithinDryRunSimulateRealImport(){var r=run(row("A",60)+","+row("A",60)+","+row("A",55),true);assertThat(r.created()).isEqualTo(1);assertThat(r.unchanged()).isEqualTo(1);assertThat(r.updated()).isEqualTo(1);assertThat(polls.list()).isEmpty();var real=run(row("A",60)+","+row("A",60)+","+row("A",55),false);assertThat(real.created()).isEqualTo(r.created());assertThat(real.updated()).isEqualTo(r.updated());assertThat(real.unchanged()).isEqualTo(r.unchanged());}
 @Test void sourceAndUnknownCandidatesAreRejected(){assertThat(run(row("A",60).replace("https://example.org/synthetic",""),false).failed()).isEqualTo(1);assertThat(run(row("B",60).replace("\"ballotNumber\":22","\"ballotNumber\":999"),true).failed()).isEqualTo(1);assertThat(polls.list()).isEmpty();}
 @Test void sameIndividualDateAndPercentageValidationApplies(){assertThat(run(row("A",60).replace("2026-10-18","2026-10-22"),true).failed()).isEqualTo(1);assertThat(run(row("B",60).replace("\"percentage\":60","\"percentage\":101"),true).failed()).isEqualTo(1);}
 @Test void performanceImportSetsProvenanceAndDerivedFactor(){var r=imports.run(json.readTree("["+performance()+"]"),false,true);assertThat(r.created()).isEqualTo(1);var p=jdbc.queryForMap("SELECT * FROM pollster_performance");assertThat(p.get("verified_at")).isNotNull();assertThat((BigDecimal)p.get("historical_score")).isEqualByComparingTo("1");assertThat(p.get("notes")).isEqualTo("Not electoral evidence");assertThat(imports.run(json.readTree("["+performance()+"]"),false,true).unchanged()).isEqualTo(1);}
 @Test void performanceDryRunAndUpdateAreAuditable(){assertThat(imports.run(json.readTree("["+performance()+"]"),true,true).created()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM pollster_performance",Integer.class)).isZero();imports.run(json.readTree("["+performance()+"]"),false,true);assertThat(imports.run(json.readTree("["+performance().replace("\"spreadError\":3","\"spreadError\":6")+"]"),false,true).updated()).isEqualTo(1);}
 @Test void arbitraryScoreAndMissingPerformanceSourceAreRejected(){assertThat(imports.run(json.readTree("["+performance().replace("\"round\":1","\"round\":1,\"historicalScore\":99")+"]"),false,true).failed()).isEqualTo(1);assertThat(imports.run(json.readTree("["+performance().replace("https://example.org/synthetic-history","")+"]"),true,true).failed()).isEqualTo(1);}
 @Test void calculationUsesSignedSpreadAndNeverPersists(){run(row("FIRST",60).replace("2026-10-18","2026-09-28").replace("2026-10-20","2026-09-30").replace("2026-10-21","2026-10-01"),false);var p=polls.list().getFirst();var r=calculations.calculate(new PerformanceCalculationService.Request(p.id(),LocalDate.parse("2026-10-04"),22,13,true,List.of(new ImportModels.CandidateResult(22,new BigDecimal("40")),new ImportModels.CandidateResult(13,new BigDecimal("60")))));assertThat(r.predictedSpread()).isEqualByComparingTo("20");assertThat(r.actualSpread()).isEqualByComparingTo("-20");assertThat(r.spreadError()).isEqualByComparingTo("40");assertThat(r.candidateError()).isEqualByComparingTo("20");assertThat(r.persisted()).isFalse();assertThat(jdbc.queryForObject("SELECT count(*) FROM pollster_performance",Integer.class)).isZero();}
 @Test void calculationRejectsNonFinalOrNonLatestInput(){seed();assertThatThrownBy(()->calculations.calculate(new PerformanceCalculationService.Request(polls.list().getFirst().id(),LocalDate.parse("2026-10-04"),22,13,false,List.of()))).isInstanceOf(IllegalArgumentException.class);}
 @Test void auditContainsWeightsMidpointsConfigurationAndAllExclusions(){seed();run(row("NEW",55).replace("2026-10-21T12","2026-10-22T12"),false);var all=audit.current();assertThat(all).hasSize(4);assertThat(all).allSatisfy(a->{assertThat(a.consideredPolls()).hasSize(1);assertThat(a.discardedPolls()).hasSize(1);assertThat(a.sumWeights()).isEqualByComparingTo("1");assertThat(a.oldestFieldMidpoint()).isEqualTo(LocalDateTime.parse("2026-10-19T00:00:00"));assertThat(a.aggregate().configuration()).isNotNull();assertThat(a.warnings()).isNotEmpty();});}
 @Test void qualityReadyWithSourcedValidPoll(){seed();assertThat(quality.check().status()).isEqualTo("READY");assertThat(quality.check().ready()).isTrue();}
 @Test void qualityDetectsMissingResults(){seed();jdbc.update("DELETE FROM poll_results");assertThat(quality.check().issues()).extracting(DataQualityService.Issue::code).contains("MISSING_RESULTS");assertThat(quality.check().ready()).isFalse();}
 @Test void qualityDetectsInvalidValidSumAndFuturePoll(){seed();jdbc.update("UPDATE polls SET vote_basis='VALID',published_at='2099-01-01'::timestamptz");jdbc.update("UPDATE poll_results SET original_percentage=20");assertThat(quality.check().issues()).extracting(DataQualityService.Issue::code).contains("VALID_SUM","FUTURE_POLL");}
 @Test void qualityDetectsDuplicateRegistrationAndRejectsAmbiguousImport(){seed();var p=polls.list().getFirst();polls.create(new PollRequest(p.pollster().id(),p.registrationNumber(),p.fieldStart(),p.fieldEnd(),p.publishedAt(),p.sampleSize(),p.marginOfError(),p.methodology(),p.sourceUrl(),p.voteBasis(),p.results().stream().map(r->new PollRequest.Result(r.candidateId(),r.originalPercentage())).toList()));assertThat(quality.check().issues()).extracting(DataQualityService.Issue::code).contains("DUPLICATE_REGISTRATION");assertThat(run(row("TEST-ONLY",50),false).failed()).isEqualTo(1);}
 @Test void qualityDetectsLegacyPerformanceWithoutChangingIt(){seed();imports.run(json.readTree("["+performance()+"]"),false,true);jdbc.update("UPDATE pollster_performance SET source_url=NULL,verified_at=NULL");assertThat(quality.check().issues()).extracting(DataQualityService.Issue::code).contains("PERFORMANCE_SOURCE","PERFORMANCE_UNVERIFIED");assertThat(jdbc.queryForObject("SELECT source_url FROM pollster_performance",String.class)).isNull();}
 @Test void qualityDetectsDanglingSnapshot(){seed();mvcSnapshot();jdbc.update("DELETE FROM polls");assertThat(quality.check().issues()).extracting(DataQualityService.Issue::code).contains("ORPHAN_SNAPSHOT");}
 void mvcSnapshot(){var a=audit.current().getFirst().aggregate();jdbc.update("INSERT INTO aggregate_snapshots(id,method,calculated_at,snapshot_minute,reference_date,poll_count,pollster_count,total_sample_size,payload) VALUES(?,'SIMPLE',now(),date_trunc('minute',now()),current_date,1,1,1500,CAST(? AS jsonb))",UUID.randomUUID(),json.writeValueAsString(a));}
 @Test void freezePreservesExactIdsConfigurationAndComposition(){seed();run(row("OLDER-UNUSED",50).replace("2026-10-21T12","2026-10-20T12"),false);imports.run(json.readTree("["+performance()+"]"),false,true);var f=freeze();assertThat(f.pollIds()).containsExactly(polls.list().getFirst().id());assertThat(f.pollsterPerformanceIds()).hasSize(1);assertThat(f.aggregateResults()).hasSize(4);assertThat(f.composition().performances().getFirst().verifiedAt()).isNotNull();assertThat(freezes.active()).isEqualTo(f);}
 @Test void newOrUpdatedPollNeverChangesFreeze(){seed();var f=freeze();run(row("TEST-ONLY",30),false);run(row("NEW",80).replace("2026-10-21T12","2026-10-22T12"),false);assertThat(freezes.active()).isEqualTo(f);assertThat(audit.current().getFirst().aggregate().results()).isNotEqualTo(f.aggregateResults().getFirst().results());}
 @Test void freezeIsImmutableInDatabaseAndCannotBeReplaced(){seed();var f=freeze();assertThatThrownBy(()->jdbc.update("UPDATE pre_election_freezes SET label='Changed' WHERE id=?",f.id())).hasMessageContaining("immutable");assertThatThrownBy(()->jdbc.update("DELETE FROM pre_election_freezes WHERE id=?",f.id())).hasMessageContaining("immutable");assertThatThrownBy(this::freeze).isInstanceOf(IllegalArgumentException.class);assertThat(freezes.active()).isEqualTo(f);}
 @Test void freezeRejectsQualityErrorsAndEmptyAggregates(){assertThatThrownBy(this::freeze).isInstanceOf(IllegalArgumentException.class);seed();jdbc.update("DELETE FROM poll_results");assertThatThrownBy(this::freeze).hasMessageContaining("ERROR");assertThat(freezes.active()).isNull();}
 OfficialResultResponse official(boolean finished){var r=br.com.election.projection.ProjectionFixtures.result(OfficialElectionResult.Scope.national(),2,1000,finished?1000:500,300,200,Instant.parse("2026-10-23T12:00:00Z"),finished);return new OfficialResultResponse("TSE",true,finished?OfficialDataStatus.FINAL:OfficialDataStatus.FRESH,r.generatedAt(),false,r.scope(),r);}
 @Test void partialComparisonUsesCurrentDifferenceOnly(){seed();var r=comparison.compare(freeze(),official(false));assertThat(r.status()).isEqualTo("PARTIAL");assertThat(r.models()).hasSize(4).allSatisfy(m->{assertThat(m.currentDifference()).isNotNull();assertThat(m.finalError()).isNull();assertThat(m.candidates()).allSatisfy(c->{assertThat(c.currentDifference()).isNotNull();assertThat(c.finalError()).isNull();});});}
 @Test void finalComparisonUsesFinalErrorOnlyAndPreservedCandidateMapping(){seed();var f=freeze();jdbc.update("UPDATE candidates SET ballot_number=999 WHERE ballot_number=22");try{var r=comparison.compare(f,official(true));assertThat(r.status()).isEqualTo("FINAL");assertThat(r.models()).allSatisfy(m->{assertThat(m.finalError()).isNotNull();assertThat(m.currentDifference()).isNull();assertThat(m.candidates()).hasSize(2).allSatisfy(c->assertThat(c.finalError()).isNotNull());});}finally{jdbc.update("UPDATE candidates SET ballot_number=22 WHERE ballot_number=999");}}
 @Test void comparisonBeforeCountingReturnsFreezeWithoutError(){seed();var f=freeze();var absent=new OfficialResultResponse("TSE",true,OfficialDataStatus.UNAVAILABLE,null,false,OfficialElectionResult.Scope.national(),null);assertThat(comparison.compare(f,absent).status()).isEqualTo("NOT_STARTED");assertThat(comparison.compare(f,absent).freeze()).isEqualTo(f);assertThat(comparison.compare(null,absent).status()).isEqualTo("NO_FREEZE");}
 @Test void publicAndAdminEndpointContracts() throws Exception {mvc.perform(get("/api/pre-election-freeze")).andExpect(status().isNoContent());mvc.perform(post("/api/admin/polls/import?dryRun=true").contentType("application/json").content("{\"polls\":["+row("A",60)+"]}")).andExpect(status().isOk()).andExpect(jsonPath("$.dryRun").value(true)).andExpect(jsonPath("$.created").value(1));seed();mvc.perform(get("/api/aggregates/audit")).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(4));mvc.perform(get("/api/admin/data-quality")).andExpect(status().isOk()).andExpect(jsonPath("$.ready").value(true));mvc.perform(post("/api/admin/pre-election-freezes").contentType("application/json").content("{\"label\":\"Contract test\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.active").value(true));mvc.perform(get("/api/pre-election-freeze")).andExpect(status().isOk()).andExpect(jsonPath("$.aggregateResults.length()").value(4));mvc.perform(get("/api/election/president/pre-election-comparison")).andExpect(status().isOk());}
 @Test void directPerformanceCalculationEndpointDoesNotPersist() throws Exception {
  mvc.perform(post("/api/admin/pollster-performances/calculate").contentType("application/json").content("""
   {"candidateA":22,"candidateB":13,"officialFinal":true,"completeCandidateSet":false,
    "predictedCandidateResults":[{"ballotNumber":22,"percentage":46},{"ballotNumber":13,"percentage":43}],
    "actualCandidateResults":[{"ballotNumber":22,"percentage":47.03},{"ballotNumber":13,"percentage":45.16}]}
   """)).andExpect(status().isOk()).andExpect(jsonPath("$.candidateError").value(1.03))
   .andExpect(jsonPath("$.predictedSpread").value(3)).andExpect(jsonPath("$.actualSpread").value(1.87))
   .andExpect(jsonPath("$.spreadError").value(1.13)).andExpect(jsonPath("$.persisted").value(false));
  assertThat(polls.list()).isEmpty();assertThat(jdbc.queryForObject("SELECT count(*) FROM pollster_performance",Long.class)).isZero();
 }
}
